// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Step 2: Read the register": "in1_Step2Readtheregister", "Read the directory": "in2_Readthedirectory", "Step 10: Read sharing": "in3_Step10Readsharing", "Step 10: Read the index": "in4_Step10Readtheindex"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 10: Read the index";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
// Each action's request bodies, the same fields the n8n build's steps write.
const actionBodies = (a) => {
  const cfg = $('Config').first().json;
  const admin = cfg.register_admin, form = cfg.owner_form_url;
  return Object.assign({}, a, {
    key_q: encodeURIComponent(a.key), source_q: encodeURIComponent(a.source), file_q: encodeURIComponent(a.file_id || ''),
    reserve_body: JSON.stringify({ p_recipe: 'R13.2', p_key: a.key }),
    withdrawn_body: JSON.stringify({ status: 'withdrawn', withdrawn_reason: a.reason }),
    withdraw_message: JSON.stringify({ to: admin, subject: 'Source withdrawn: ' + (a.title || a.source),
      text: a.title + ' has ' + a.reason + ', so it is withdrawn and answers nothing until it has an owner and dates.' }),
    reassign_exception: JSON.stringify({ recipe: 'R13.2', item: a.source, reason: 'owner left',
      detail: a.title + ': ' + a.reason + ' (' + a.owner + ')', owner: admin }),
    reassign_message: JSON.stringify({ to: admin, subject: 'Reassign the owner: ' + a.title,
      text: a.title + ': ' + a.reason + ' (' + a.owner + '). Name a new owner in the register.' }),
    remind_message: JSON.stringify({ to: a.recipient, subject: 'Review due: ' + a.title,
      text: a.title + ' is due for review on ' + a.review_date + '. It is withdrawn from answers on ' + a.pull_date +
            ' unless you renew, replace or retire it: ' + form }),
    archive_body: JSON.stringify({ folder: cfg.archive_folder }),
    expired_message: JSON.stringify({ to: a.recipient, cc: admin, subject: 'Withdrawn: ' + a.title,
      text: a.title + ' passed its expiry date (' + a.pull_date + ') and is withdrawn and archived. Renew, replace or retire it: ' + form }),
    mismatch_exception: JSON.stringify({ recipe: 'R13.2', item: a.source, reason: 'register mismatch', detail: a.title + ': ' + a.reason, owner: admin }),
    mismatch_message: JSON.stringify({ to: admin, subject: 'Register mismatch: ' + a.title, text: a.title + ': ' + a.reason }),
    done_body: JSON.stringify({ status: 'done', result: a.action }),
    log_body: JSON.stringify({ recipe: 'R13.2', item: a.source, decision: a.action,
      rules: { reason: a.reason, week_key: a.key, recipient: a.recipient || null, pull_date: a.pull_date || null } }),
    failed_body: JSON.stringify({ recipe: 'R13.2', item: a.source, reason: 'write failed',
      detail: 'Step ' + a.action + ' failed part way; check the source, never retried', owner: admin }),
  });
};
const BODIES = (out) => ({"weekly_log_body": JSON.stringify({ recipe: 'R13.2', item: 'week ' + out.week, decision: 'weekly check', rules: { sources_checked: out.checked, actions: out.actions.map(a => a.source + ': ' + a.action) } }), "split": out.actions.map(actionBodies)});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Steps 2, 4 to 7 and 10 of the book's R13.2, in order. One action per source and need;
// the duplicate key (step 3) is source, week and action, so one source can need two actions.
const cfg = $('Config').first().json;
const rows = $('Step 2: Read the register').first().json.items || [];
const users = Object.fromEntries(($('Read the directory').first().json.items || []).map(u => [String(u.id).toLowerCase(), u]));
const files = Object.fromEntries(($('Step 10: Read sharing').first().json.items || []).map(f => [String(f.id), f]));
const indexed = Object.fromEntries(($('Step 10: Read the index').first().json.items || []).map(s => [String(s.id), s]));

const DAY = 86400000;
const iso = d => d.toISOString().slice(0, 10);
const day = s => new Date(String(s).slice(0, 10) + 'T00:00:00Z');
const today = day(new Date().toISOString());
// ISO week, such as 2026-W43: the "week" in the duplicate key.
const t = new Date(today); t.setUTCDate(t.getUTCDate() + 3 - ((t.getUTCDay() + 6) % 7));
const w1 = new Date(Date.UTC(t.getUTCFullYear(), 0, 4));
const week = `${t.getUTCFullYear()}-W${String(1 + Math.round(((t - w1) / DAY - 3 + ((w1.getUTCDay() + 6) % 7)) / 7)).padStart(2, '0')}`;
const dueBy = new Date(today.getTime() + cfg.due_within_days * DAY);
const major = v => parseInt(String(v), 10);
const sameSet = (a, b) => { const x = [...new Set((a || []).map(String))].sort(), y = [...new Set((b || []).map(String))].sort(); return x.join('|') === y.join('|'); };

const actions = [];
let checked = 0;
for (const r of rows) {
  if (cfg.inactive_statuses.includes(r.status)) continue;  // already withdrawn or retired: the owner decides (step 8)
  checked++;
  const base = { source: String(r.id), title: r.title, owner: r.owner || null, file_id: r.file_id || null };
  const add = (action, extra) => actions.push(Object.assign({}, base, { action, key: `${r.id}:${week}:${action}` }, extra));

  // Step 4: no owner or review date means withdrawn, with the register admin alerted.
  if (!r.owner || !r.review_date) { add('withdraw_missing', { reason: !r.owner ? 'no owner' : 'no review date' }); continue; }

  const pull = r.expiry_date ? day(r.expiry_date) : new Date(day(r.review_date).getTime() + cfg.expiry_after_review_days * DAY);
  const expired = pull < today;
  // Step 5: a departed owner goes to the register admin to reassign; one on vacation, to the delegate.
  const u = users[String(r.owner).toLowerCase()];
  const departed = !u || u.active === false;
  const recipient = departed ? cfg.register_admin : (u.on_leave ? (r.delegate || cfg.register_admin) : r.owner);
  if (departed) add('reassign', { reason: u ? 'owner has left' : 'owner not in the directory' });

  if (expired) {
    // Step 7: past expiry: withdraw, archive, tell the owner (or who stands in) and the register admin.
    add('withdraw_expired', { recipient, pull_date: iso(pull), reason: 'past expiry' });
    continue;
  }
  // Step 6: due within the window, or past review: remind the owner with the pull date.
  if (!departed && day(r.review_date) <= dueBy) {
    add('remind', { recipient, review_date: iso(day(r.review_date)), pull_date: iso(pull),
                    reason: day(r.review_date) < today ? 'past review' : 'review due' });
  }
  // Step 10: stored audience against live sharing, and register version against the index.
  if (r.status === 'current') {
    const f = files[String(r.file_id)], ix = indexed[String(r.id)];
    const problems = [];
    if (!f || !sameSet(r.audience, f.shared_with)) problems.push('audience differs from sharing');
    if (!ix || major(ix.version) !== major(r.version)) problems.push(`register version ${r.version}, index ${ix ? ix.version : 'missing'}`);
    if (problems.length) add('mismatch', { reason: problems.join('; ') });
  }
}
return [{ json: { week, checked, actions } }];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));
